function processEscapes(str) {
    return str.replace(/\\([nrt'"\\])/g, function(match, esc) {
        switch(esc) {
            case 'n': return '\n';
            case 'r': return '\r';
            case 't': return '\t';
            case '"': return '"';
            case "'": return "'";
            case '\\': return '\\';
            default: return match;
        }
    });
}

